import { Button } from '@refy-design/web';
import { Message } from '@refy-design/web';
import { MessageScroller } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function MessageScrollerExample() {
  const [messages, setMessages] = useState(
    Array.from({ length: 8 }, (_, i) => `Project update ${i + 1}.`),
  );
  return (
    <div style={stack}>
      <MessageScroller>
        {messages.map((text, i) => (
          <Message
            key={i}
            author={i % 3 === 1 ? 'You' : 'Ana Lima'}
            initials={i % 3 === 1 ? 'VC' : 'AL'}
            time={`10:${String(30 + i).padStart(2, '0')}`}
            side={i % 3 === 1 ? 'end' : 'start'}
          >
            {text}
          </Message>
        ))}
      </MessageScroller>
      <Button
        onClick={() =>
          setMessages((rows) => [...rows, `Project update ${rows.length + 1}.`])
        }
      >
        New message
      </Button>
    </div>
  );
}
export function Example() {
  return <MessageScrollerExample />;
}
